catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }
   function ResponseFunction(response){
	try{
		var results = JSON.parse(response);
		if(results.error){
			alert(results.error);
			return;
		};

		//upload MRVS varlable set
		if(results.success && results.data && results.data.length > 0){

			//set data to MRVS
			g_form.setValue('data_set',JSON.stringify(results.data));

			// show success message
			alert('successfully imported'+ results.data.length + 'records');
		}else{
			alert('No valid data found in Excel file');
		}
	}catch(e){
		alert('Error processing response');
	}
   }

   // called  server_side script
   if(newValue){
	var ga = new GlideAjax('readEXCEL');
	ga.addParam('sysparm_name','getData');
	ga.addParam('sysparm_id',newValue);
	ga.getXMLAnswer(ResponseFunction);
   }



}
